import { useCallback, useEffect, useRef, useState } from "react";
import { PageHeader } from "@kerfjs/ui/page-header";
import { StateBanner } from "@kerfjs/ui/state-banner";
import { EmptyState } from "@kerfjs/ui/empty-state";
import { LoadingSpinner } from "@kerfjs/ui/loading-spinner";
import "@kerfjs/ui/layout.css";
import "./ListWorkspace.css";

export type Item = { id: string; title: string };
export function ListWorkspace({ load, onCreate }: {
  load: (signal: AbortSignal) => Promise<Item[]>; onCreate: () => void;
}) {
  const [items, setItems] = useState<Item[] | null>(null);
  const [pending, setPending] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const request = useRef<AbortController | null>(null);
  const refresh = useCallback(async () => {
    request.current?.abort();
    const controller = new AbortController();
    request.current = controller;
    setPending(true);
    setError(null);
    try {
      const data = await load(controller.signal);
      if (!controller.signal.aborted) setItems(data);
    } catch {
      if (!controller.signal.aborted) setError("We could not load your items. Please try again.");
    } finally {
      if (!controller.signal.aborted) setPending(false);
    }
  }, [load]);
  useEffect(() => { void refresh(); return () => request.current?.abort(); }, [refresh]);
  return <main className="kui-layout list-workspace">
    <PageHeader title="Items">
      <button type="button" disabled={pending} onClick={() => void refresh()}>Refresh</button>
    </PageHeader>
    <div className="list-body">
      <div role="status" aria-live="polite" aria-atomic="true">
        {pending && <span><LoadingSpinner aria-hidden="true" />{items === null ? "Loading items…" : "Refreshing items. Previous results remain visible."}</span>}
      </div>
      {error && <StateBanner role="alert" variant="danger">
        <strong>Items unavailable</strong><p>{error}</p>
        {items !== null && <p>Showing the last successfully loaded results.</p>}
        <button type="button" onClick={() => void refresh()}>Try again</button>
      </StateBanner>}
      <section aria-label="Items" aria-busy={pending}>
        {items !== null && items.length === 0 && <EmptyState title="No items yet"
          description="Create your first item to begin.">
          <button type="button" onClick={onCreate}>Create item</button>
        </EmptyState>}
        {items !== null && items.length > 0 && <ul>
          {items.map(item => <li key={item.id}>{item.title}</li>)}
        </ul>}
      </section>
    </div>
  </main>;
}

